import ipaddress, socket
from urllib.parse import urlsplit

ALLOWED_HOSTS = {"images.partner.example"}

def check_destination(url, resolve=socket.getaddrinfo):
    parts = urlsplit(url)
    if parts.scheme != "https":
        raise ValueError("scheme not allowed")
    if parts.hostname not in ALLOWED_HOSTS:
        raise ValueError("host not on allowlist")
    ips = {info[4][0] for info in resolve(parts.hostname, 443)}
    for ip in ips:
        if not ipaddress.ip_address(ip).is_global:
            raise ValueError(f"{ip} is not a public address")
    return parts.hostname, sorted(ips)

