  if (start < 0) return msg;
  String key = msg.substring(start + 2, msg.indexOf("}", start));
  String prefix = key.substring(0, key.indexOf(':'));
  String value = lookups.get(prefix).lookup(key);
  return format(msg.replace("${" + key + "}", value));
}

